(async () => {
    const browser = await chromium.launch();
    const results = {};
    const errors = [];
    const page = await browser.newPage();
    page.on('console', msg => { if (msg.type() === 'error') errors.push('console: ' + msg.text()); });
    page.on('pageerror', err => errors.push('pageerror: ' + err.message));
    page.on('requestfailed', req => errors.push('requestfailed: ' + req.url() + ' ' + (req.failure()||{}).errorText));

    // 1) Main page: index selectbox should be populated from ES
    await page.goto('http://localhost/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(3000);
    const indexOptions = await page.$eval('#chooseIndex', el => Array.from(el.options).map(o => o.textContent.trim())).catch(e => ['ERR ' + e.message]);
    results.mainPage_indexSelect = indexOptions;

    // 2) Spotify example page: filter field selectbox should be populated from index mapping
    await page.goto('http://localhost/examples/spotify/indexSpotify.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(3000);
    const spotifyFields = await page.$eval('#dataExplorerDataFields', el => Array.from(el.options).map(o => o.textContent.trim())).catch(e => ['ERR ' + e.message]);
    results.spotifyPage_filterFields = spotifyFields;

    // 3) Select a field and run a search to prove end-to-end data retrieval + rendering
    if (spotifyFields.length > 1) {
        await page.click('.oneCollapsibleItem.filter .collapsible-header'); await page.waitForTimeout(1000); await page.selectOption('#dataExplorerDataFields', spotifyFields[1]);
        await page.waitForTimeout(1000);
        // Choose bar chart output if present
        const hasOutputOptions = await page.$eval('#outputControls select', el => el.options.length).catch(() => 0);
        await page.click('.oneCollapsibleItem.output .collapsible-header'); await page.waitForTimeout(1000);
        if (hasOutputOptions > 1) {
            await page.selectOption('#outputControls select', { index: 0 });
        }
        await page.waitForTimeout(500);
        await page.click('#getResults');
        await page.waitForTimeout(5000);
        const svgCount = await page.locator('#graphicsWrapper svg').count();
        const feedback = await page.$eval('#feedbackText', el => el.textContent.trim()).catch(() => '');
        results.spotifyPage_afterRun = { svgCount, feedback };
    }

    // 4) PHP proxy page reachable & executes
    const proxyStatus = await page.goto('http://localhost/php/dataExplorerProxy.php', { waitUntil: 'networkidle' }).catch(() => null);
    results.proxyPage_reachable = proxyStatus ? proxyStatus.status() : 'ERR';

    results.errors = errors;
    console.log('VERIFY_RESULTS:' + JSON.stringify(results, null, 2));
    await browser.close();
})().catch(e => { console.error('VERIFY_FAILED', e); process.exit(1); });
